SELECT , (SELECT COUNT(1) FROM t_requirement_repo_rel rr WHERE rr.repo_id = tr.repo_id) AS requirement_count FROM t_requirement_repo tr LEFT JOIN t_requirement_project tp ON tr.project_id = tp.project_id
AND tr.project_id = #{queryForm.projectId}
AND INSTR(tr.repo_name, #{queryForm.repoName})
AND tr.status = #{queryForm.status}
ORDER BY tr.create_time DESC

SELECT *
FROM t_requirement_repo
WHERE project_id = #{projectId}
  AND repo_name = #{repoName}

    AND repo_id != #{excludeRepoId}

LIMIT 1
